/* Считаем количество карточек, которые были спроектированы John Avon и у которых нет фольклорной версии. */
SELECT COUNT(*) 
FROM cards AS T1
JOIN rulings AS T2 ON T1.uuid = T2.uuid
WHERE T1.artist LIKE 'John Avon' AND T2.date BETWEEN '2020-01-01' AND '2020-12-31';

