/* Находим уникальный код набора с наибольшим количеством карточек */
SELECT setcode 
FROM cards 
GROUP BY setcode 
ORDER BY COUNT(*) DESC 
LIMIT 1;

/* Проверяем, принадлежит ли карта "Angel of Mercy" набору, который также содержалась в MTGO */
SELECT DISTINCT c.setcode
FROM cards c
JOIN set_translations st ON c.setcode = st.setcode
WHERE c.name LIKE '%Angel of Mercy%'
AND st.translation LIKE '%Magic%The%Gathering%Online%';

/* Calculate the percentage of cards whose language is French among the Story Spotlight cards */
WITH story_spotlight_cards AS (
    SELECT *
    FROM foreign_data
    WHERE name LIKE '%Story Spot%'
)
SELECT 
    ROUND(
        (COUNT(CASE WHEN language = 'French' THEN 1 ELSE NULL END)::FLOAT / COUNT(*)) * 100,
        2
    ) AS percentage_french
FROM story_spotlight_cards;
